	CFrame.Angles(0, math.rad(-180), math.rad(-90)),
	CFrame.Angles(0, math.rad(90), math.rad(-90)),
	CFrame.Angles(math.rad(90), math.rad(90), 0),
	CFrame.Angles(0, math.rad(90), 0),
	CFrame.Angles(math.rad(-90), math.rad(90), 0),
}

local function alloc(len: number)
	if outgoing_used + len > outgoing_size then
		while outgoing_used + len > outgoing_size do
			outgoing_size = outgoing_size * 2
		end

		local new_buff = buffer.create(outgoing_size)
		buffer.copy(new_buff, 0, outgoing_buff, 0, outgoing_used)

		outgoing_buff = new_buff
	end

	outgoing_apos = outgoing_used
	outgoing_used = outgoing_used + len

	return outgoing_apos
end

local function read(len: number)
	local pos = incoming_read
	incoming_read = incoming_read + len

	return pos
end

local function save()
	return {
		buff = outgoing_buff,
		used = outgoing_used,
		size = outgoing_size,
		inst = outgoing_inst,
		outgoing_ids = outgoing_ids,
		incoming_ids = incoming_ids,
	}
end

local function load(data: {
	buff: buffer,
	used: number,
	size: number,
	inst: { Instance },
	outgoing_ids: { number },
	incoming_ids: { number },
})
	outgoing_buff = data.buff
	outgoing_used = data.used
	outgoing_size = data.size
	outgoing_inst = data.inst
	outgoing_ids = data.outgoing_ids
	incoming_ids = data.incoming_ids
end

local function load_empty()
	outgoing_buff = buffer.create(64)
	outgoing_used = 0
	outgoing_size = 64
	outgoing_inst = {}
	outgoing_ids = {}
	incoming_ids = {}
end

load_empty()

local types = {}

local polling_queues_reliable = {}
local polling_queues_unreliable = {}
if not RunService:IsRunning() then
	local noop = function() end
	return table.freeze({
		SendEvents = noop,
		RetreatEgg = table.freeze({
			Call = noop
		}),
		RequestEgg = table.freeze({
			Call = noop
		}),
		PickupCreature = table.freeze({
			Call = noop
		}),
	}) :: Events
end
local remotes = ReplicatedStorage:WaitForChild("ZAP")

local reliable = remotes:WaitForChild("ZAP_RELIABLE")
assert(reliable:IsA("RemoteEvent"), "Expected ZAP_RELIABLE to be a RemoteEvent")

export type EggActionResultCode = ("Claimed" | "ClaimLostRace" | "EggNotFound" | "EggUnavailable" | "EggObjectUnavailable" | "NoCharacter" | "TooFar" | "CarryingCreature" | "ProfileNotReady" | "NoPetEquipped" | "PetRecovering" | "FightInProgress" | "InvalidPet" | "RateLimited" | "ServerError")
export type FightActionResultCode = ("Retreated" | "FightNotActive" | "RateLimited" | "ServerError")
export type CarryActionResultCode = ("PickedUp" | "CreatureNotFound" | "CreatureUnavailable" | "NoCharacter" | "TooFar" | "CarryingCreature" | "PickupLockedOut" | "DropExpired" | "RateLimited" | "ServerError")

local function SendEvents()
	if outgoing_used ~= 0 then
		local buff = buffer.create(outgoing_used)
		buffer.copy(buff, 0, outgoing_buff, 0, outgoing_used)

		reliable:FireServer(buff, outgoing_inst)

		outgoing_buff = buffer.create(64)
		outgoing_used = 0
		outgoing_size = 64
		table.clear(outgoing_inst)
	end
end

RunService.Heartbeat:Connect(SendEvents)

local reliable_events = table.create(3)
local reliable_event_queue: { [number]: { any } } = table.create(3)
local function_call_id = 0
reliable_event_queue[1] = table.create(255)
reliable_event_queue[0] = table.create(255)
reliable_event_queue[2] = table.create(255)
reliable.OnClientEvent:Connect(function(buff, inst)
	incoming_buff = buff
	incoming_inst = inst
	incoming_read = 0
	incoming_ipos = 0
	local len = buffer.len(buff)
	while incoming_read < len do
		local id = buffer.readu8(buff, read(1))
		if id == 1 then -- RetreatEgg
			local call_id = buffer.readu8(incoming_buff, read(1))
			local value
			local bool_1 = buffer.readu8(incoming_buff, read(1))
			if bit32.btest(bool_1, 0b0000000000000001) then
				value = "Retreated"
			elseif bit32.btest(bool_1, 0b0000000000000010) then
				value = "FightNotActive"
			elseif bit32.btest(bool_1, 0b0000000000000100) then
				value = "RateLimited"
			elseif bit32.btest(bool_1, 0b0000000000001000) then
				value = "ServerError"
			end
			local thread = reliable_event_queue[1][call_id]
			-- When using actors it's possible for multiple Zap clients to exist, but only one called the Zap remote function.
			if thread then
				task.spawn(thread, value)
			end
			reliable_event_queue[1][call_id] = nil
		elseif id == 0 then -- RequestEgg
			local call_id = buffer.readu8(incoming_buff, read(1))
			local value
			local bool_2 = buffer.readu16(incoming_buff, read(2))
			if bit32.btest(bool_2, 0b0000000000000001) then
				value = "Claimed"
			elseif bit32.btest(bool_2, 0b0000000000000010) then
				value = "ClaimLostRace"
			elseif bit32.btest(bool_2, 0b0000000000000100) then
				value = "EggNotFound"
			elseif bit32.btest(bool_2, 0b0000000000001000) then
				value = "EggUnavailable"
			elseif bit32.btest(bool_2, 0b0000000000010000) then
				value = "EggObjectUnavailable"
			elseif bit32.btest(bool_2, 0b0000000000100000) then
				value = "NoCharacter"
			elseif bit32.btest(bool_2, 0b0000000001000000) then
				value = "TooFar"
			elseif bit32.btest(bool_2, 0b0000000010000000) then
				value = "CarryingCreature"
			elseif bit32.btest(bool_2, 0b0000000100000000) then
				value = "ProfileNotReady"
			elseif bit32.btest(bool_2, 0b0000001000000000) then
				value = "NoPetEquipped"
			elseif bit32.btest(bool_2, 0b0000010000000000) then
				value = "PetRecovering"
			elseif bit32.btest(bool_2, 0b0000100000000000) then
				value = "FightInProgress"
			elseif bit32.btest(bool_2, 0b0001000000000000) then
				value = "InvalidPet"
			elseif bit32.btest(bool_2, 0b0010000000000000) then
				value = "RateLimited"
			elseif bit32.btest(bool_2, 0b0100000000000000) then
				value = "ServerError"
			end
			local thread = reliable_event_queue[0][call_id]
			-- When using actors it's possible for multiple Zap clients to exist, but only one called the Zap remote function.
			if thread then
				task.spawn(thread, value)
			end
			reliable_event_queue[0][call_id] = nil
		elseif id == 2 then -- PickupCreature
			local call_id = buffer.readu8(incoming_buff, read(1))
			local value
			local bool_3 = buffer.readu16(incoming_buff, read(2))
			if bit32.btest(bool_3, 0b0000000000000001) then
				value = "PickedUp"
			elseif bit32.btest(bool_3, 0b0000000000000010) then
				value = "CreatureNotFound"
			elseif bit32.btest(bool_3, 0b0000000000000100) then
				value = "CreatureUnavailable"
			elseif bit32.btest(bool_3, 0b0000000000001000) then
				value = "NoCharacter"
			elseif bit32.btest(bool_3, 0b0000000000010000) then
				value = "TooFar"
			elseif bit32.btest(bool_3, 0b0000000000100000) then
				value = "CarryingCreature"
			elseif bit32.btest(bool_3, 0b0000000001000000) then
				value = "PickupLockedOut"
			elseif bit32.btest(bool_3, 0b0000000010000000) then
				value = "DropExpired"
			elseif bit32.btest(bool_3, 0b0000000100000000) then
				value = "RateLimited"
			elseif bit32.btest(bool_3, 0b0000001000000000) then
				value = "ServerError"
			end
			local thread = reliable_event_queue[2][call_id]
			-- When using actors it's possible for multiple Zap clients to exist, but only one called the Zap remote function.
			if thread then
				task.spawn(thread, value)
			end
			reliable_event_queue[2][call_id] = nil
		else
			error("Unknown event id")
		end
	end
end)
table.freeze(polling_queues_reliable)
table.freeze(polling_queues_unreliable)

local returns = {
